    def rotate_matrix(mat):
    m, n = len(mat), len(mat[0])
    res = [[0] * m for _ in range(n)]

    # Transpose the matrix
    for i in range(m):
        for j in range(n):
            res[j][i] = mat[i][j]

    # Reverse each column (not row) of the result which is a n x m matrix
    for j in range(m):
        for i in range(n // 2):
            res[i][j], res[n - i - 1][j] = res[n - i - 1][j], res[i][j]

    return res

